// HasDNSProvider applies the HasEdge predicate on the "dns_provider" edge.
func HasDNSProvider() predicate.DNSZone {
	return predicate.DNSZone(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.M2O, false, DNSProviderTable, DNSProviderColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasDNSProviderWith applies the HasEdge predicate on the "dns_provider" edge with a given conditions (other predicates).
func HasDNSProviderWith(preds ...predicate.DNSProvider) predicate.DNSZone {
	return predicate.DNSZone(func(s *sql.Selector) {
		step := newDNSProviderStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// And groups predicates with the AND operator between them.
func And(predicates ...predicate.DNSZone) predicate.DNSZone {
	return predicate.DNSZone(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.DNSZone) predicate.DNSZone {
	return predicate.DNSZone(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.DNSZone) predicate.DNSZone {
	return predicate.DNSZone(sql.NotPredicates(p))
}
